//! Parity tests for `gpt_sovits_text::cleaner` against fixtures generated by
//! `parity/cleaner/gen_fixtures.py`.
//!
//! Cases that reach `chinese2` (v2 `zh`, also through `clean_special`) need
//! the G2PW model: set `G2PW_MODEL_DIR` to the extracted `G2PWModel_1.1`
//! directory (the `g2pw-model` task of `pixi.toml` puts it in
//! `parity/.cache/G2PWModel`). Without it those cases are skipped (and the test says so); the
//! other languages are always checked. The `version` environment variable
//! must be unset, as it is for the generator.
//!
//! Every case must match exactly, except the Japanese cases listed in
//! `ja_exceptions`. `CLEANER_VERBOSE=1` prints every mismatch.

#[path = "common/e2e_common.rs"]
mod e2e_common;

use std::collections::BTreeMap;
use std::sync::LazyLock;

use e2e_common::{g2pw_model_dir, lines};
use gpt_sovits_text::Cleaner;
use gpt_sovits_text::chinese2::Chinese2;
use gpt_sovits_text::cleaner::{CleanedText, Error};
use serde_json::{Value, json};

/// `(cause, language, version, text)` cases whose output differs from
/// upstream. The only cause is `UNKNOWN_KANJINUMERIC_GROUP`, a difference of
/// the `japanese` module's MeCab tokenizer port that is not documented there
/// and is reported as a bug (see the `exc` docs in `tests/e2e.rs`).
fn ja_exceptions() -> Vec<(&'static str, &'static str, Option<&'static str>, String)> {
  let long_zh = "这是一个很长的句子".repeat(60) + "。";
  vec![
    (
      "UNKNOWN_KANJINUMERIC_GROUP",
      "ja",
      None,
      "《三体》是一部科幻小说。".to_string(),
    ),
    ("UNKNOWN_KANJINUMERIC_GROUP", "ja", None, long_zh.clone()),
    ("UNKNOWN_KANJINUMERIC_GROUP", "ja", Some("v1"), long_zh),
  ]
}

static WITH_G2PW: LazyLock<Option<Cleaner>> =
  LazyLock::new(|| g2pw_model_dir().map(|dir| Cleaner::new(dir).unwrap()));
static WITHOUT_G2PW: LazyLock<Cleaner> =
  LazyLock::new(|| Cleaner::from_chinese2(Chinese2::without_g2pw()));

fn encode(r: Result<CleanedText, Error>) -> Value {
  match r {
    Ok((phones, word2ph, norm)) => {
      json!({"phones": phones.join(" "), "word2ph": word2ph, "norm": norm})
    }
    Err(e) => json!({"error": e.name()}),
  }
}

/// Whether the case runs `chinese2.g2p`: v2 `zh` in `clean_text` or
/// `clean_special`.
fn needs_g2pw(language: &str, version: Option<&str>) -> bool {
  language == "zh" && version != Some("v1")
}

fn cleaner_for(language: &str, version: Option<&str>) -> Option<&'static Cleaner> {
  if needs_g2pw(language, version) {
    WITH_G2PW.as_ref()
  } else {
    Some(&WITHOUT_G2PW)
  }
}

#[derive(Default)]
struct Report {
  stats: BTreeMap<String, (usize, usize)>,
  skipped: usize,
  mismatches: Vec<(String, Option<String>, String)>,
}

impl Report {
  fn check(
    &mut self,
    key: String,
    language: &str,
    version: Option<&str>,
    text: &str,
    want: &Value,
    got: Value,
  ) {
    let entry = self.stats.entry(key).or_default();
    entry.0 += 1;
    if &got == want {
      entry.1 += 1;
    } else {
      if std::env::var("CLEANER_VERBOSE").is_ok() {
        eprintln!("[{language} {version:?}] {text:?}\n  want {want}\n  got  {got}");
      }
      self.mismatches.push((
        language.to_string(),
        version.map(str::to_string),
        text.to_string(),
      ));
    }
  }

  fn finish(self, name: &str, exceptions: &[(&str, &str, Option<&str>, String)]) {
    for (k, (n, ok)) in &self.stats {
      eprintln!("{name} {k}: {ok}/{n}");
    }
    if self.skipped > 0 {
      eprintln!(
        "{name}: skipped {} cases that need G2PW_MODEL_DIR",
        self.skipped
      );
    }
    let mut got: Vec<(String, Option<String>, String)> = self.mismatches;
    got.sort();
    let mut want: Vec<(String, Option<String>, String)> = exceptions
      .iter()
      .filter(|(_, l, v, _)| self.skipped == 0 || !needs_g2pw(l, *v))
      .map(|(_, l, v, t)| (l.to_string(), v.map(str::to_string), t.clone()))
      .collect();
    want.sort();
    assert_eq!(
      got, want,
      "{name}: mismatches differ from the exception list"
    );
  }
}

#[test]
fn clean_text_matches_python() {
  assert!(std::env::var_os("version").is_none(), "unset `version`");
  let mut report = Report::default();
  for rec in lines(include_str!("fixtures/cleaner/clean_text.jsonl")) {
    let text = rec["text"].as_str().unwrap();
    let language = rec["language"].as_str().unwrap();
    let version = rec["version"].as_str();
    let Some(cleaner) = cleaner_for(language, version) else {
      report.skipped += 1;
      continue;
    };
    let got = encode(cleaner.clean_text(text, language, version));
    let key = format!("{language:?} version={}", version.unwrap_or("None"));
    report.check(key, language, version, text, &rec["out"], got);
  }
  report.finish("clean_text", &ja_exceptions());
}

#[test]
fn clean_special_matches_python() {
  let mut report = Report::default();
  for rec in lines(include_str!("fixtures/cleaner/clean_special.jsonl")) {
    let text = rec["text"].as_str().unwrap();
    let language = rec["language"].as_str().unwrap();
    let special_s = rec["special_s"].as_str().unwrap();
    let target = rec["target_symbol"].as_str().unwrap();
    let Some(cleaner) = cleaner_for(language, None) else {
      report.skipped += 1;
      continue;
    };
    let got = encode(cleaner.clean_special(text, language, special_s, target, None));
    report.check(
      format!("{language:?} {special_s}"),
      language,
      None,
      text,
      &rec["out"],
      got,
    );
  }
  report.finish("clean_special", &[]);
}

#[test]
fn text_to_sequence_matches_python() {
  for rec in lines(include_str!("fixtures/cleaner/text_to_sequence.jsonl")) {
    let text = rec["text"].as_str().unwrap();
    let language = rec["language"].as_str().unwrap();
    let got = match WITHOUT_G2PW.text_to_sequence(text, language, None) {
      Ok(ids) => json!(ids),
      Err(e) => json!({"error": e.name()}),
    };
    assert_eq!(got, rec["out"], "text_to_sequence({text:?}, {language:?})");
  }
}

/// The languages that are not ported return `NotPorted` instead of falling
/// back to another module.
#[test]
fn not_ported_languages() {
  let c = &*WITHOUT_G2PW;
  for (language, version) in [("ko", None), ("ko", Some("v2")), ("zh", Some("v1"))] {
    let e = c
      .clean_text("안녕하세요 你好", language, version)
      .unwrap_err();
    assert!(matches!(e, Error::NotPorted { .. }), "{e}");
    assert_eq!(e.name(), "NotPortedError");
  }
  // v1 has no `ko` or `yue`: they fall back to ("en", " ") as upstream.
  let (phones, word2ph, norm) = c.clean_text("안녕", "ko", Some("v1")).unwrap();
  assert_eq!(
    (phones, word2ph, norm.as_str()),
    (vec![",".to_string()], None, " ")
  );
  // `clean_special` with a flat-list `g2p` is not ported either.
  for language in ["en", "ja"] {
    let e = c
      .clean_special("a^b", language, "^", "SP3", None)
      .unwrap_err();
    assert!(matches!(e, Error::NotPorted { .. }), "{e}");
  }
}
